scwin.dts_Corp_OnLoadCompleted = function(rowcount) {
    if (scwin.vBzProcsNo == "") {
        buttonSet.setInsertStatus();
        scwin.fn_initForm('C');
    } else {
        scwin.fn_initForm('X');
        if ($c.stf.getObjectValue(edt_LIST_DD) > scwin.vCurDate) {
            buttonSet.setUpdateStatus();
        } else {
            buttonSet.setErrorStatus(); //disable 시킨다.

        }
    }
    if ($c.stf.getObjectValue(txb_LIST_NO) != "") {
        img_LIST_NO.src = "../img/btn_LstNoCrt_d.gif";
        img_LIST_NO.setDisabled(true);
    }
};
scwin.trs_Save_OnFail = function() {
    $c.lc.fn_alertMsg('F');
    $c.stf.alert_error(trs_Save);
};
scwin.trs_Save_OnSuccess = async function() {
    $c.lc.fn_alertMsg('S');
    scwin.fn_parentRefresh();

    //20100910 (2616) 회사정보 저장 후 '상장종목신규'버튼 활성화
    scwin.fn_btnShow(scwin.vBzProcsNo);
    if (buttonSet.status == "U") {
        var parentWin = $c.frame.path("../");
        parentWin.dts_List.setFocusedCell(scwin.rowPos, 0);
    }
    if (buttonSet.status == "D") {
        // 삭제처리의 응답인 경우
        await $c.frame.CloseFrame();
    } else {
        scwin.fn_read_sync();
    }
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.cmb_SPOT_ISU_TRD_MKT_TP_CD_OnSelChange = function() {
    if ($c.stf.getObjectValue(cmb_SPOT_ISU_TRD_MKT_TP_CD) == "1") {
        $c.stf.showObj(label_58, true);
        $c.stf.showObj(label_32, false);
        edt_ACNTCLS_MM1.Format = "MM월 DD일";
    } else if ($c.stf.getObjectValue(cmb_SPOT_ISU_TRD_MKT_TP_CD) == "2") {
        $c.stf.showObj(label_58, false);
        $c.stf.showObj(label_32, true);
        edt_ACNTCLS_MM1.Format = "MM월";
    } else {
        $c.stf.showObj(label_58, true);
        $c.stf.showObj(label_32, false);
        edt_ACNTCLS_MM1.Format = "MM월 DD일";
    }
};
scwin.gform_onload = function() {
    if (js_market == "1") {
        $c.stf.showObj(panel_KOSDAQ, false);
        $c.stf.showObj(panel_KOSDAQ1, false);
        $c.stf.showObj(panel_KSE, true);
        $c.stf.showObj(panel_APPL_EXCHRT, false);
    } else if (js_market == "2") {
        $c.stf.showObj(panel_KOSDAQ, true);
        $c.stf.showObj(panel_KOSDAQ1, true);
        $c.stf.showObj(panel_KSE, false);
        $c.stf.showObj(panel_APPL_EXCHRT, true);
    } else {
        scwin.pJsMarket = '1';
    }
    $c.libRoundPanel.PanelToGroupBox(panel_Top);
    $c.libRoundPanel.PanelToGroupBox(panel_Item);
    scwin.fn_searchCode();
    scwin.fn_SetComboCode();
    var parentWin = $c.frame.path("../");
    scwin.vBzProcsNo = parentWin.scwin.clickBzProcsNo;
    scwin.rowPos = parentWin.dts_List.getFocusedRowIndex();

    /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
    buttonSet.setSaveInfo(btn_Save, fn_save); // 저장

    buttonSet.setDsclInfo(btn_Dscl, fn_dscl); // 안내문작성

    //20100910 (2616) 회사정보 저장 후 '상장종목신규'버튼 활성화
    scwin.fn_btnShow(scwin.vBzProcsNo);
    if (scwin.vBzProcsNo != "") {
        scwin.fn_read_sync();
        txb_SearchCd.setValue(dts_Corp.getCellData(1, "ISUR_CD"));
        txb_SearchNm.setValue(dts_Corp.getCellData(1, "COM_NM"));
        cmb_SECUGRP_ID.setDisabled(true);
    } else {
        $c.stf.setObjectValue(cmb_SECUGRP_ID, $c.stf.getObjectValue(parentWin.cmb_NEW_SECUGRP_ID)); //부모창에서 증권그룹값이 가져온다.
        $c.stf.setObjectValue(cmb_SPOT_ISU_TRD_MKT_TP_CD, scwin.pJsMarket);
        buttonSet.setInsertStatus();
    }
    scwin.fn_kindStkGridNameChange($c.stf.getObjectValue(cmb_SECUGRP_ID));
    if ($c.stf.getObjectValue(cmb_SPOT_ISU_TRD_MKT_TP_CD) == "1") {
        $c.stf.showObj(label_58, true);
        $c.stf.showObj(label_32, false);
        edt_ACNTCLS_MM1.Format = "MM월 DD일";
    } else if ($c.stf.getObjectValue(cmb_SPOT_ISU_TRD_MKT_TP_CD) == "2") {
        $c.stf.showObj(label_58, false);
        $c.stf.showObj(label_32, true);
        edt_ACNTCLS_MM1.Format = "MM월";
    } else {
        $c.stf.showObj(label_58, true);
        $c.stf.showObj(label_32, false);
        edt_ACNTCLS_MM1.Format = "MM월 DD일";
    }
};
